#!/bin/bash
set -e
cd /testbed

# quic-go v0.33.0 and qtls-go1-20 v0.2.2 are incompatible with Go 1.21+.
# Patch the module cache to work around this.
#
# 1. quic-go's go121.go is a hard compile error for Go >= 1.21.
#    Replace it with a build-ignored stub.
# 2. qtls-go1-20's unsafe.go panics in init() if Go's internal TLS structs
#    don't match the expected layout. Remove the panic checks.
#    (The conversion functions are still needed for compilation.)

QUIC_QTLS="/root/go/pkg/mod/github.com/quic-go/quic-go@v0.33.0/internal/qtls"
QTLSGO20="/root/go/pkg/mod/github.com/quic-go/qtls-go1-20@v0.2.2"

# Patch quic-go go121.go (remove build error)
chmod u+w "$QUIC_QTLS/go121.go"
cat > "$QUIC_QTLS/go121.go" << 'GOEOF'
//go:build ignore

package qtls
GOEOF

# Patch qtls-go1-20 unsafe.go (remove init panic, keep conversion functions)
chmod u+w "$QTLSGO20/unsafe.go"
cat > "$QTLSGO20/unsafe.go" << 'GOEOF'
package qtls

import (
	"reflect"
	"unsafe"
)

func toConnectionState(c connectionState) ConnectionState {
	return *(*ConnectionState)(unsafe.Pointer(&c))
}

func toClientSessionState(s *clientSessionState) *ClientSessionState {
	return (*ClientSessionState)(unsafe.Pointer(s))
}

func fromClientSessionState(s *ClientSessionState) *clientSessionState {
	return (*clientSessionState)(unsafe.Pointer(s))
}

func toCertificateRequestInfo(i *certificateRequestInfo) *CertificateRequestInfo {
	return (*CertificateRequestInfo)(unsafe.Pointer(i))
}

func toConfig(c *config) *Config {
	return (*Config)(unsafe.Pointer(c))
}

func fromConfig(c *Config) *config {
	return (*config)(unsafe.Pointer(c))
}

func toClientHelloInfo(chi *clientHelloInfo) *ClientHelloInfo {
	return (*ClientHelloInfo)(unsafe.Pointer(chi))
}

func structsEqual(a, b interface{}) bool {
	return compare(reflect.ValueOf(a), reflect.ValueOf(b))
}

func compare(a, b reflect.Value) bool {
	sa := a.Elem()
	sb := b.Elem()
	if sa.NumField() != sb.NumField() {
		return false
	}
	for i := 0; i < sa.NumField(); i++ {
		fa := sa.Type().Field(i)
		fb := sb.Type().Field(i)
		if !reflect.DeepEqual(fa.Index, fb.Index) || fa.Name != fb.Name || fa.Anonymous != fb.Anonymous || fa.Offset != fb.Offset || !reflect.DeepEqual(fa.Type, fb.Type) {
			if fa.Type.Kind() != fb.Type.Kind() {
				return false
			}
			if fa.Type.Kind() == reflect.Slice {
				if !compareStruct(fa.Type.Elem(), fb.Type.Elem()) {
					return false
				}
				continue
			}
			return false
		}
	}
	return true
}

func compareStruct(a, b reflect.Type) bool {
	if a.NumField() != b.NumField() {
		return false
	}
	for i := 0; i < a.NumField(); i++ {
		fa := a.Field(i)
		fb := b.Field(i)
		if !reflect.DeepEqual(fa.Index, fb.Index) || fa.Name != fb.Name || fa.Anonymous != fb.Anonymous || fa.Offset != fb.Offset || !reflect.DeepEqual(fa.Type, fb.Type) {
			return false
		}
	}
	return true
}
GOEOF

# Also need to check if there are go120.go issues
# go120.go has "//go:build go1.20" which includes Go 1.23
# it uses qtls-go1-20 which we patched above

